16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.time.Period;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 format")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "birth_date")
62	    private LocalDate birthDate;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "household_id")
68	    private String householdId;
69	
70	    @Column(name = "namesake_count")
71	    private Integer namesakeCount;
72	
73	    @Column(name = "household_size")
74	    private Integer householdSize;
75	
76	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
77	    private Set<Pet> pets;
78	
79	    public String getAddress() {
80	        return this.address;
81	    }
82	
83	    public void setAddress(String address) {
84	        this.address = address;
85	    }
86	
87	    public String getCity() {
88	        return this.city;
89	    }
90	
91	    public void setCity(String city) {
92	        this.city = city;
93	    }
94	
95	    public String getTelephone() {
96	        return this.telephone;
97	    }
98	
99	    public void setTelephone(String telephone) {
100	        this.telephone = telephone;
101	    }
102	
103	    public String getEmail() {
104	        return this.email;
105	    }
106	
107	    public void setEmail(String email) {
108	        this.email = email;
109	    }
110	
111	    public String getPostcode() {
112	        return this.postcode;
113	    }
114	
115	    public void setPostcode(String postcode) {
116	        this.postcode = postcode;
117	    }
118	
119	    public LocalDate getRegistrationDate() {
120	        return this.registrationDate;
121	    }
122	
123	    public void setRegistrationDate(LocalDate registrationDate) {
124	        this.registrationDate = registrationDate;
125	    }
126	
127	    public LocalDate getBirthDate() {
128	        return this.birthDate;
129	    }
130	
131	    public void setBirthDate(LocalDate birthDate) {
132	        this.birthDate = birthDate;
133	    }
134	
135	    public String getCustomerCode() {
136	        return this.customerCode;
137	    }
138	
139	    public void setCustomerCode(String customerCode) {
140	        this.customerCode = customerCode;
141	    }
142	
143	    public String getHouseholdId() {
144	        return this.householdId;
145	    }
146	
147	    public void setHouseholdId(String householdId) {
148	        this.householdId = householdId;
149	    }
150	
151	    public Integer getNamesakeCount() {
152	        return this.namesakeCount;
153	    }
154	
155	    public void setNamesakeCount(Integer namesakeCount) {
156	        this.namesakeCount = namesakeCount;
157	    }
158	
159	    public Integer getHouseholdSize() {
160	        return this.householdSize;
161	    }
162	
163	    public void setHouseholdSize(Integer householdSize) {
164	        this.householdSize = householdSize;
165	    }
166	
167	    /**
168	     * The owner's identity key: the single derived value used to detect duplicate owners, formed
169	     * as {@code normalizedTelephone + '|' + email + '|' + householdId} where an absent telephone,
170	     * email or household contributes an empty string. Two owners are duplicates only when their
171	     * whole identity keys are equal, so housemates that share a {@code householdId} but hold
172	     * different telephones have distinct identity keys and are both allowed.
173	     */
174	    public String getIdentityKey() {
175	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
176	    }
177	
178	    private static String orEmpty(String value) {
179	        return value == null ? "" : value;
180	    }
181	
182	    /**
183	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
184	     * last two digits of the registration date's year (e.g. {@code 'SMI-0007-M26'}). Derived
185	     * from the owner's own fields; absent until both the customer code and registration date
186	     * have been assigned.
187	     */
188	    public String getMembershipNumber() {
189	        if (this.customerCode == null || this.registrationDate == null) {
190	            return null;
191	        }
192	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
193	    }
194	
195	    /**
196	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of the
197	     * {@link #getCustomerCode() customer code}. Absent until the customer code has been assigned.
198	     */
199	    public Integer getCheckDigit() {
200	        if (this.customerCode == null) {
201	            return null;
202	        }
203	        return Luhn.checkDigit(this.customerCode);
204	    }
205	
206	    /**
207	     * The owner's membership level, a number from 1 to 3 derived from the owner's own fields:
208	     * every owner starts at level 1, gains a level when an email address is present, and gains a
209	     * further level when this owner has no namesakes ({@code namesakeCount} is 0). The result is
210	     * capped at 3; level 4 is reserved for tenure.
211	     */
212	    public Integer getMembershipLevel() {
213	        int level = 1;
214	        boolean hasEmail = this.email != null && !this.email.isEmpty();
215	        if (hasEmail) {
216	            level++;
217	        }
218	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
219	        if (unique) {
220	            level++;
221	        }
222	        return Math.min(level, 3);
223	    }
224	
225	    /**
226	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customer code} (the
227	     * region derived from the postcode when the identity was assigned), or {@link Regions#UNKNOWN}
228	     * before a customer code has been assigned.
229	     */
230	    public String getLocality() {
231	        if (this.customerCode == null) {
232	            return Regions.UNKNOWN;
233	        }
234	        int separator = this.customerCode.indexOf('-');
235	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
236	    }
237	
238	    /**
239	     * The owner's preferred contact channel, derived from the owner's own fields:
240	     * {@code "EMAIL"} when an {@link #getEmail() email} is present, otherwise {@code "PHONE"}.
241	     */
242	    public String getContactPreference() {
243	        boolean hasEmail = this.email != null && !this.email.isEmpty();
244	        return hasEmail ? "EMAIL" : "PHONE";
245	    }
246	
247	    /**
248	     * The owner's age band, derived from the owner's own fields: the whole years between
249	     * {@link #getBirthDate() birth date} and {@link #getRegistrationDate() registration date}
250	     * classified as {@code "MINOR"} (under 18), {@code "ADULT"} (18-64) or {@code "SENIOR"}
251	     * (65 or older). Absent until a birth date and a registration date are both present.
252	     */
253	    public String getAgeBand() {
254	        if (this.birthDate == null || this.registrationDate == null) {
255	            return null;
256	        }
257	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
258	        if (age < 18) {
259	            return "MINOR";
260	        }
261	        return age < 65 ? "ADULT" : "SENIOR";
262	    }
263	
264	    /**
265	     * Resolve the effective registration date before persisting: default it to the server's
266	     * current date when none was supplied, then roll it forward off weekends so a newly
267	     * registered owner always has a business-day registration date. Every value derived from it
268	     * (such as the {@link #getMembershipNumber() membership number}) therefore uses the adjusted
269	     * date.
270	     */
271	    @PrePersist
272	    private void resolveRegistrationDate() {
273	        if (this.registrationDate == null) {
274	            this.registrationDate = LocalDate.now();
275	        }
276	        this.registrationDate = BusinessDay.onOrAfter(this.registrationDate);
277	    }
278	
279	    protected Set<Pet> getPetsInternal() {
280	        if (this.pets == null) {
281	            this.pets = new HashSet<>();
282	        }
283	        return this.pets;
284	    }
285	
286	    protected void setPetsInternal(Set<Pet> pets) {
287	        this.pets = pets;
288	    }
289	
290	    public List<Pet> getPets() {
291	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
292	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
293	        return Collections.unmodifiableList(sortedPets);
294	    }
295	
296	    public void setPets(List<Pet> pets) {
297	        this.pets = new HashSet<>(pets);
298	    }
299	
300	    public void addPet(Pet pet) {
301	        getPetsInternal().add(pet);
302	        pet.setOwner(this);
303	    }
304	
305	    /**
306	     * Return the Pet with the given name, or null if none found for this Owner.
307	     *
308	     * @param name to test
309	     * @return true if pet name is already in use
310	     */
311	    public Pet getPet(String name) {
312	        return getPet(name, false);
313	    }
314	
315	    /**
316	     * Return the Pet with the given name, or null if none found for this Owner.
317	     *
318	     * @param name to test
319	     * @return true if pet name is already in use
320	     */
321	    public Pet getPet(String name, boolean ignoreNew) {
322	        name = name.toLowerCase();
323	        for (Pet pet : getPetsInternal()) {
324	            if (!ignoreNew || !pet.isNew()) {
325	                String compName = pet.getName();
326	                compName = compName.toLowerCase();
327	                if (compName.equals(name)) {
328	                    return pet;
329	                }
330	            }
