29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.rest.assignment.CustomerCodeGenerator;
39	import org.springframework.samples.petclinic.rest.assignment.HouseholdIdGenerator;
40	import org.springframework.samples.petclinic.rest.assignment.HouseholdRegistrar;
41	import org.springframework.samples.petclinic.rest.audit.OwnerAuditLogger;
42	import org.springframework.samples.petclinic.rest.signup.BulkSignupWarningEvaluator;
43	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
44	import org.springframework.samples.petclinic.rest.validation.CityOwnerLimitValidator;
45	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitValidator;
46	import org.springframework.samples.petclinic.rest.validation.DuplicateOwnerValidator;
47	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
48	import org.springframework.samples.petclinic.rest.validation.OwnerRequestValidator;
49	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
50	import org.springframework.samples.petclinic.rest.validation.RegistrationDateValidator;
51	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
52	import org.springframework.samples.petclinic.service.ClinicService;
53	import org.springframework.security.access.prepost.PreAuthorize;
54	import org.springframework.web.bind.annotation.CrossOrigin;
55	import org.springframework.web.bind.annotation.RequestMapping;
56	import org.springframework.web.bind.annotation.RestController;
57	import org.springframework.web.util.UriComponentsBuilder;
58	
59	import jakarta.transaction.Transactional;
60	
61	/**
62	 * @author Vitaliy Fedoriv
63	 */
64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    private final OwnerRequestValidator ownerRequestValidator;
79	
80	    private final PostcodeValidator postcodeValidator;
81	
82	    private final DuplicateOwnerValidator duplicateOwnerValidator;
83	
84	    private final CityOwnerLimitValidator cityOwnerLimitValidator;
85	
86	    private final DailyOwnerLimitValidator dailyOwnerLimitValidator;
87	
88	    private final RegistrationDateValidator registrationDateValidator;
89	
90	    private final TelephoneNormalizer telephoneNormalizer;
91	
92	    private final EmailNormalizer emailNormalizer;
93	
94	    private final AddressNormalizer addressNormalizer;
95	
96	    private final CustomerCodeGenerator customerCodeGenerator;
97	
98	    private final HouseholdIdGenerator householdIdGenerator;
99	
100	    private final HouseholdRegistrar householdRegistrar;
101	
102	    private final OwnerAuditLogger ownerAuditLogger;
103	
104	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
105	
106	    public OwnerRestControllerV1(ClinicService clinicService,
107	                                 OwnerMapper ownerMapper,
108	                                 PetMapper petMapper,
109	                                 VisitMapper visitMapper,
110	                                 OwnerRequestValidator ownerRequestValidator,
111	                                 PostcodeValidator postcodeValidator,
112	                                 DuplicateOwnerValidator duplicateOwnerValidator,
113	                                 CityOwnerLimitValidator cityOwnerLimitValidator,
114	                                 DailyOwnerLimitValidator dailyOwnerLimitValidator,
115	                                 RegistrationDateValidator registrationDateValidator,
116	                                 TelephoneNormalizer telephoneNormalizer,
117	                                 EmailNormalizer emailNormalizer,
118	                                 AddressNormalizer addressNormalizer,
119	                                 CustomerCodeGenerator customerCodeGenerator,
120	                                 HouseholdIdGenerator householdIdGenerator,
121	                                 HouseholdRegistrar householdRegistrar,
122	                                 OwnerAuditLogger ownerAuditLogger,
123	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator) {
124	        this.clinicService = clinicService;
125	        this.ownerMapper = ownerMapper;
126	        this.petMapper = petMapper;
127	        this.visitMapper = visitMapper;
128	        this.ownerRequestValidator = ownerRequestValidator;
129	        this.postcodeValidator = postcodeValidator;
130	        this.duplicateOwnerValidator = duplicateOwnerValidator;
131	        this.cityOwnerLimitValidator = cityOwnerLimitValidator;
132	        this.dailyOwnerLimitValidator = dailyOwnerLimitValidator;
133	        this.registrationDateValidator = registrationDateValidator;
134	        this.telephoneNormalizer = telephoneNormalizer;
135	        this.emailNormalizer = emailNormalizer;
136	        this.addressNormalizer = addressNormalizer;
137	        this.customerCodeGenerator = customerCodeGenerator;
138	        this.householdIdGenerator = householdIdGenerator;
139	        this.householdRegistrar = householdRegistrar;
140	        this.ownerAuditLogger = ownerAuditLogger;
141	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
142	    }
143	
144	    /**
145	     * Map an owner to its DTO and stamp the current bulk-signup warning onto it, so every
146	     * single-owner response reflects whether more than 80 owners have been created today.
147	     */
148	    private OwnerDto toOwnerDto(Owner owner) {
149	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
150	        ownerDto.setBulkSignupWarning(this.bulkSignupWarningEvaluator.isBulkSignupInEffect());
151	        return ownerDto;
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Override
156	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
157	        Collection<Owner> owners;
158	        if (lastName != null) {
159	            owners = this.clinicService.findOwnerByLastName(lastName);
160	        } else {
161	            owners = this.clinicService.findAllOwners();
162	        }
163	        if (owners.isEmpty()) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Override
171	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
172	        Owner owner = this.clinicService.findOwnerById(ownerId);
173	        if (owner == null) {
174	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
175	        }
176	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
182	        ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
183	        this.ownerRequestValidator.validate(ownerFieldsDto);
184	        this.postcodeValidator.validate(ownerFieldsDto);
185	        this.cityOwnerLimitValidator.validate(ownerFieldsDto);
186	        this.registrationDateValidator.validate(ownerFieldsDto.getRegistrationDate());
187	        this.dailyOwnerLimitValidator.validate(ownerFieldsDto.getRegistrationDate());
188	        ownerFieldsDto.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
189	        ownerFieldsDto.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
190	        HttpHeaders headers = new HttpHeaders();
191	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
192	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
193	        if (sharesHousehold) {
194	            owner.setHouseholdId(
195	                this.householdIdGenerator.generate(owner.getLastName(), owner.getAddress()));
196	        }
197	        this.duplicateOwnerValidator.validate(owner);
198	        owner.setCustomerCode(
199	            this.customerCodeGenerator.generate(owner.getPostcode(), owner.getTelephone(),
200	                owner.getLastName()));
201	        owner.setNamesakeCount(
202	            (int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
203	        if (sharesHousehold) {
204	            owner.setHouseholdSize(this.householdRegistrar.register(owner));
205	        }
206	        this.clinicService.saveOwner(owner);
207	        this.ownerAuditLogger.created(owner);
208	        OwnerDto ownerDto = toOwnerDto(owner);
209	        headers.setLocation(UriComponentsBuilder.newInstance()
210	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
211	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
217	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
218	        if (currentOwner == null) {
219	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
220	        }
221	        currentOwner.setAddress(ownerFieldsDto.getAddress());
222	        currentOwner.setCity(ownerFieldsDto.getCity());
223	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
224	        currentOwner.setLastName(ownerFieldsDto.getLastName());
225	        currentOwner.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
226	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
227	        this.clinicService.saveOwner(currentOwner);
228	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
229	    }
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Transactional
233	    @Override
234	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
235	        Owner owner = this.clinicService.findOwnerById(ownerId);
236	        if (owner == null) {
237	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
238	        }
239	        this.clinicService.deleteOwner(owner);
240	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
241	    }
242	
243	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
244	    @Override
245	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
246	        Owner owner = this.clinicService.findOwnerById(ownerId);
247	        if (owner == null) {
248	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
249	        }
250	        HttpHeaders headers = new HttpHeaders();
251	        Pet pet = petMapper.toPet(petFieldsDto);
252	        owner.setId(ownerId);
253	        pet.setOwner(owner);
254	        pet.getType().setName(null);
255	        this.clinicService.savePet(pet);
256	        PetDto petDto = petMapper.toPetDto(pet);
257	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
258	            .buildAndExpand(pet.getId()).toUri());
259	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
260	    }
261	
262	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
263	    @Override
264	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
265	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
266	        if (currentOwner != null) {
267	            Pet currentPet = this.clinicService.findPetById(petId);
268	            if (currentPet != null) {
269	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
270	                currentPet.setName(petFieldsDto.getName());
271	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
272	                this.clinicService.savePet(currentPet);
273	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
274	            }
275	        }
276	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
277	    }
278	
279	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
280	    @Override
281	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
282	        HttpHeaders headers = new HttpHeaders();
283	        Visit visit = visitMapper.toVisit(visitFieldsDto);
284	        Pet pet = new Pet();
285	        pet.setId(petId);
286	        visit.setPet(pet);
287	        this.clinicService.saveVisit(visit);
288	        VisitDto visitDto = visitMapper.toVisitDto(visit);
289	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
290	            .buildAndExpand(visit.getId()).toUri());
